mapper.select:
select  from prepaid_consume_record_t

    prepaid_consume_record_t.id = #{id}
    and prepaid_consume_record_t.is_delete = 0

select date(prepaid_consume_record_t.consume_time) as bucketDate, sum(case when prepaid_consume_record_t.amount < 0 then -prepaid_consume_record_t.amount else 0 end) as expenseAmount, sum(case when prepaid_consume_record_t.amount >= 0 then prepaid_consume_record_t.amount else 0 end) as rechargeAmount from prepaid_consume_record_t
prepaid_consume_record_t.is_delete = 0
and prepaid_consume_record_t.card_id = #{cardId}
and prepaid_consume_record_t.consume_time >= #{startDate}
and prepaid_consume_record_t.consume_time < date_add(#{endDate}, interval 1 day)
group by date(prepaid_consume_record_t.consume_time) order by bucketDate asc

select
  sum(case when prepaid_consume_record_t.amount < 0 then -prepaid_consume_record_t.amount else 0 end) as expenseAmount,
  sum(case when prepaid_consume_record_t.amount >= 0 then prepaid_consume_record_t.amount else 0 end) as rechargeAmount
from prepaid_consume_record_t

    prepaid_consume_record_t.is_delete = 0

        and prepaid_consume_record_t.card_id = #{cardId}


        and prepaid_consume_record_t.consume_time >= #{startTime}


        and prepaid_consume_record_t.consume_time < #{endTime}
